typedef struct {
    char ip[16];  // IPv4 addresses are typically 4 octets, e.g., <ip-address>
} IPAddress;

/**
 * @brief Structure to represent the IP blocker system
 */
typedef struct {
    IPAddress* blacklist;  // Array of blacklisted IP addresses
    int blacklist_size;    // Number of entries in the blacklist
    int max_blacklist_size; // Maximum capacity of the blacklist
} IPBlocker;

/**
 * @brief Initialize the IPBlocker system
 * @param blocker Pointer to the IPBlocker structure to initialize
 * @param initial_capacity Initial capacity for the blacklist array
 * @return 0 on success, -1 on failure (memory allocation error)
 */
int ip_blocker_init(IPBlocker* blocker, int initial_capacity) {
    if (blocker == NULL || initial_capacity <= 0) {
        return -1;
    }

    blocker->max_blacklist_size = initial_capacity;
    blocker->blacklist_size = 0;
    blocker->blacklist = (IPAddress*)malloc(initial_capacity * sizeof(IPAddress));

    if (blocker->blacklist == NULL) {
        return -1;
    }

    return 0;
}

/**
 * @brief Clean up the IPBlocker system
 * @param blocker Pointer to the IPBlocker structure to free
 */
void ip_blocker_cleanup(IPBlocker* blocker) {
    if (blocker != NULL && blocker->blacklist != NULL) {
        free(blocker->blacklist);
        blocker->blacklist = NULL;
        blocker->blacklist_size = 0;
        blocker->max_blacklist_size = 0;
    }
}

