// Function to safely read a configuration file
int read_config_file(const char* filename, char** buffer, size_t* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening configuration file");
        return -1;
    }

    // Determine file size first
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size == 0) {
        fclose(file);
        return 0;
    }

    // Allocate memory for the buffer
    *size = file_size;
    *buffer = (char*)malloc(file_size + 1);
    if (!*buffer) {
        perror("Error allocating memory for configuration buffer");
        fclose(file);
        return -1;
    }

    // Read the file content
    if (fread(*buffer, 1, file_size, file) != file_size) {
        perror("Error reading configuration file");
        free(*buffer);
        fclose(file);
        return -1;
    }

    // Null-terminate the string
    (*buffer)[file_size] = '\0';

    fclose(file);
    return 0;
}

