        return -1;
    }

    ssize_t bytes_read = read(fd, key, KEY_SIZE);
    close(fd);

    if (bytes_read != KEY_SIZE) {
        syslog(LOG_ERR, "Incomplete key read from file: %zd bytes read instead of %d", bytes_read, KEY_SIZE);
        return -1;
    }

    return 0;
}

