int create_backup(const char* original_path, const char* backup_path) {
    FILE* original = fopen(original_path, "r");
    FILE* backup = fopen(backup_path, "w");

    if (!original || !backup) {
        perror("Error opening files for backup");
        return -1;
    }

    char buffer[4096];
    while (fgets(buffer, sizeof(buffer), original)) {
        fprintf(backup, "%s", buffer);
    }

    fclose(original);
    fclose(backup);

    return 0;
}

