// Simple CIDR class to check if an IP is within a CIDR range
class CIDR {
public:
    struct Range {
        std::string network;
        std::string mask;
        std::string description;
    };

    static bool isWithinRange(const std::string& ip, const std::string& cidr) {
        // Parse CIDR notation (e.g., <ip-address>/24)
        size_t slashPos = cidr.find('/');
        if (slashPos == std::string::npos) return false;

        std::string network = cidr.substr(0, slashPos);
        std::string maskStr = cidr.substr(slashPos + 1);

        // Convert IP to 32-bit integer
        uint32_t ipInt = inet_addr(ip.c_str());
        if (ipInt == INADDR_NONE) return false;

        // Convert mask to 32-bit integer
        uint32_t maskInt = 0;
        for (int i = 0; i < 32; ++i) {
            if (maskStr[i] == '0') {
                maskInt |= (1U << (31 - i));
            } else if (maskStr[i] == '1') {
                maskInt |= (1U << (31 - i));
            }
        }

        // Convert network to 32-bit integer
        uint32_t networkInt = inet_addr(network.c_str());
        if (networkInt == INADDR_NONE) return false;

        // Check if IP is within the network
        return (ipInt & maskInt) == (networkInt & maskInt);
    }

    static bool isWithinRange(const std::string& ip, const Range& range) {
        return isWithinRange(ip, range.network + "/" + range.mask);
    }
};

