        }
    }

    // Convert IP to a simple numeric representation for comparison
    uint32_t toNumeric() const {
        std::istringstream iss(address);
        std::string octet;
        uint32_t result = 0;

        int count = 0;
        while (std::getline(iss, octet, '.')) {
            if (count >= 4) break;
            int num = std::stoi(octet);
            if (num < 0 || num > 255) return 0;
            result = (result << 8) | num;
            count++;
        }

        return result;
    }

    bool operator==(const IPAddress& other) const {
        return address == other.address;
    }

    bool operator<(const IPAddress& other) const {
        return address < other.address;
    }
};

