    // Safe copy with bounds checking
    void safeCopy(const char* src, size_t max_copy_size) {
        if (!src) {
            std::cerr << "Null pointer passed to safeCopy" << std::endl;
            return;
        }

        size_t src_len = strlen(src);
        size_t copy_size = std::min(src_len, max_copy_size);

        if (copy_size >= capacity) {
            std::cerr << "Buffer overflow detected: source length exceeds capacity!" << std::endl;
            std::cerr << "Source length: " << src_len << ", Capacity: " << capacity << std::endl;
            std::cerr << "Terminating program to prevent crash." << std::endl;
            exit(EXIT_FAILURE);
        }

        memcpy(data, src, copy_size);
        data[copy_size] = '\0';
        length = copy_size;
    }

