        log4cpp::FileAppender* fileAppender = new log4cpp::FileAppender("network_log", "network_traffic.log");
        fileAppender->setLayout(layout);
        root.addAppender(fileAppender);

        if (level == "ERROR") {
            root.error(message);
        } else if (level == "WARNING") {
            root.warn(message);
        } else if (level == "INFO") {
            root.info(message);
        } else {
            root.debug(message);
        }
    }

    static void logBlock(const std::string& ip, const std::string& reason) {
        log("INFO", "Blocked IP: " + ip + " | Reason: " + reason);
    }

    static void logUpdate(const std::string& source, const std::string& action) {
        log("INFO", "Blacklist update from " + source + " | Action: " + action);
    }
};

