// Class to represent a CIDR block
class CIDRBlock {
public:
    std::string network;
    int prefixLength;

    CIDRBlock(const std::string& net, int prefix) : network(net), prefixLength(prefix) {}

    // Check if an IP address is within this CIDR block
    bool contains(const std::string& ip) const {
        if (network.empty() || prefixLength < 0 || prefixLength > 32) return false;

        // Convert IP to unsigned long long
        unsigned long long ipNum = inet_pton(AF_INET, ip.c_str());
        if (ipNum == 0) return false;

        // Convert network to unsigned long long
        unsigned long long netNum = inet_pton(AF_INET, network.c_str());
        if (netNum == 0) return false;

        // Calculate the mask
        unsigned long long mask = 0xFFFFFFFFUL << (32 - prefixLength);

        // Check if the IP is within the network
        return (ipNum & mask) == (netNum & mask);
    }
};

