class SecureDataRepository {
private:
    std::map<std::string, std::string> authorizedUsers;

    // Load authorized users and passwords from a configuration file
    bool loadConfiguration(const std::string& filename) {
        std::ifstream file(filename);
        if (!file.is_open()) {
            std::cerr << "Error: Could not open configuration file " << filename << std::endl;
            return false;
        }

        std::string line;
        while (std::getline(file, line)) {
            // Skip empty lines and comments
            if (line.empty() || line[0] == '#') {
                continue;
            }

            std::istringstream iss(line);
            std::string username, password;

            if (std::getline(iss, username, ':') && std::getline(iss, password)) {
                authorizedUsers[username] = password;
            } else {
                std::cerr << "Error: Invalid format in configuration file." << std::endl;
                return false;
            }
        }

        file.close();
        return true;
    }

public:
    SecureDataRepository(const std::string& configFilename = "config.txt") {
        if (!loadConfiguration(configFilename)) {
            // If configuration fails, set an empty map (no access)
            authorizedUsers.clear();
        }
    }

    // Check if a user has access to the repository
    bool hasAccess(const std::string& username, const std::string& password) {
        auto it = authorizedUsers.find(username);
        if (it != authorizedUsers.end()) {
            return it->second == password;
        }
        return false;
    }

    // Method to check if the repository is loaded successfully
    bool isConfigLoaded() const {
        return !authorizedUsers.empty();
    }
};

