     */
    public boolean updateConfiguration(Map<String, String> parameters) {
        try {
            // Create a backup of the original configuration file
            if (Files.exists(Paths.get(CONFIG_FILE_PATH))) {
                Files.copy(Paths.get(CONFIG_FILE_PATH), 
                          Paths.get(BACKUP_DIR), 
                          StandardCopyOption.REPLACE_EXISTING);
            }

            // Read the current configuration file
            StringBuilder configBuilder = new StringBuilder();
            try (BufferedReader reader = Files.newBufferedReader(Paths.get(CONFIG_FILE_PATH))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    configBuilder.append(line).append("\n");
                }
            }

            // Apply the provided parameters to the configuration
            for (Map.Entry<String, String> entry : parameters.entrySet()) {
                String key = entry.getKey();
                String value = entry.getValue();

                // Replace specific configuration keys with new values
                if (key.contains("Environment")) {
                    configBuilder.append("Environment=").append(value).append("\n");
                } else if (key.contains("WorkingDirectory")) {
                    configBuilder.append("WorkingDirectory=").append(value).append("\n");
                } else if (key.contains("User")) {
                    configBuilder.append("User=").append(value).append("\n");
                }
            }

            // Write the updated configuration back to the file
