class DDOSBlocker:
    def __init__(self, timeout_hours: int = 24):
        self.timeout_hours = timeout_hours
        self.blocked_ips: Dict[str, datetime.datetime] = {}
        self.blocked_ips_file = "blocked_ips.json"

    def is_ip_blocked(self, ip: str) -> bool:
        """Check if an IP address is currently blocked."""
        return ip in self.blocked_ips

    def get_block_duration(self, ip: str) -> Optional[int]:
        """Get the remaining duration (in hours) for a blocked IP."""
        if ip not in self.blocked_ips:
            return None

        now = datetime.datetime.now()
        duration = (self.blocked_ips[ip] - now).total_seconds()
        if duration <= 0:
            return None

        return int(duration / 3600)

    def add_block(self, ip: str) -> bool:
        """Add an IP address to the block list and update iptables."""
        if self.is_ip_blocked(ip):
            logging.warning(f"IP {ip} is already blocked. Skipping addition.")
            return False

        # Record the block time
        self.blocked_ips[ip] = datetime.datetime.now()

        # Update iptables to block the IP
        try:
            # Use iptables to append a rule to block the IP
            subprocess.run([
                'iptables', '-A', 'INPUT', '-s', ip, '-j', 'DROP'
            ], check=True, capture_output=True)

            logging.info(f"Successfully blocked IP {ip} for {self.timeout_hours} hours.")
            return True

        except subprocess.CalledProcessError as e:
            logging.error(f"Failed to block IP {ip}: {e.stderr.decode()}")
            return False

    def remove_block(self, ip: str) -> bool:
        """Remove an IP address from the block list and update iptables."""
        if ip not in self.blocked_ips:
            logging.warning(f"IP {ip} is not blocked. Skipping removal.")
            return False
